from collections import deque

def build(vals):
    n = len(vals)
    L = [-1] * n; R = [-1] * n
    for i in range(1, n):
        v = vals[i]; cur = 0
        while True:
            if v < vals[cur]:
                if L[cur] < 0:
                    L[cur] = i; break
                cur = L[cur]
            else:
                if R[cur] < 0:
                    R[cur] = i; break
                cur = R[cur]
    out = []
    q = deque([0])
    while q:
        x = q.popleft()
        if x == -1:
            out.append('null')
        else:
            out.append(str(vals[x]))
            q.append(L[x]); q.append(R[x])
    while out and out[-1] == 'null':
        out.pop()
    return ' '.join(out)

def fmt(vals, target, k):
    return build(vals) + '\n' + str(target) + ' ' + str(k)

def gen(rng):
    t = [fmt([5], 100, 1), fmt([5], -3, 1), fmt([4, 2, 6], 5, 2), fmt([4, 2, 6], 5, 3), fmt([10, 5, 15, 3, 7, 12, 20], 11, 4)]
    t.append(fmt([1, 2, 3, 4, 5, 6, 7], 0, 3))
    t.append(fmt([7, 6, 5, 4, 3, 2, 1], 100, 5))
    t.append(fmt([0, 10**9], 10**9 // 2, 1))
    for n in (2, 3, 4, 6, 8, 10, 14, 20):
        for _ in range(3):
            vals = rng.sample(range(0, 40), n)
            t.append(fmt(vals, rng.randint(-5, 45), rng.randint(1, n)))
    # chain-like deep tree
    vals = list(range(0, 1600, 2))
    t.append(fmt(vals, 777, 300))
    # large random BSTs
    for n, k in ((100000, 50000), (100000, 1), (30000, 30000)):
        vals = rng.sample(range(0, 10**9 + 1), n)
        t.append(fmt(vals, rng.randint(0, 10**9), k))
    vals = list(range(100000)); rng.shuffle(vals)
    t.append(fmt(vals, 50000, 777))
    return t

